-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): refinery capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- INTERMEDIATE
--   Fields read with the switch on: amassoma_cdu_utilisation_pct.
--   The plan table rounds utilisation to whole percent; the prompt asks 2
--   decimals.
--   APPENDED: Read the figures in the Refinery Planning & Scheduling Studio with
--   its Full precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/refinery.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- refinery / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'refinery' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w3 refinery refused: refinery/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '10ca9eaf03451bbe27ad60f70bcd431c' and fields = '[{"key": "amassoma_crude_run_bbl", "tol": 0.5, "unit": "barrels", "label": "Total crude run of the optimal plan", "expected": 1880000}, {"key": "amassoma_cdu_utilisation_pct", "tol": 0.005, "unit": "percent", "label": "Utilisation of the crude unit", "expected": 81.73913043}, {"key": "amassoma_plan_margin_usd", "tol": 0.5, "unit": "US dollars", "label": "Plan margin for the month", "expected": 8170744}, {"key": "amassoma_gross_margin_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Gross margin per barrel of crude", "expected": 4.34614043}, {"key": "amassoma_naphtha_value_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Value to the plan of one more barrel of naphtha", "expected": 91.32}, {"key": "amassoma_gasoil_value_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Value to the plan of one more barrel of gasoil", "expected": 88.06733333}]'::jsonb then 'old'
              when md5(prompt) = 'f55920e832196c1ddcbf854acc6ebded' and fields = '[{"key": "amassoma_crude_run_bbl", "tol": 0.5, "unit": "barrels", "label": "Total crude run of the optimal plan", "expected": 1880000}, {"key": "amassoma_cdu_utilisation_pct", "tol": 0.005, "unit": "percent", "label": "Utilisation of the crude unit", "expected": 81.73913043}, {"key": "amassoma_plan_margin_usd", "tol": 0.5, "unit": "US dollars", "label": "Plan margin for the month", "expected": 8170744}, {"key": "amassoma_gross_margin_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Gross margin per barrel of crude", "expected": 4.34614043}, {"key": "amassoma_naphtha_value_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Value to the plan of one more barrel of naphtha", "expected": 91.32}, {"key": "amassoma_gasoil_value_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Value to the plan of one more barrel of gasoil", "expected": 88.06733333}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'refinery' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w3 refinery refused: refinery/intermediate matches neither its post-W1 form (prompt md5 10ca9eaf03451bbe27ad60f70bcd431c) nor its W3 form (prompt md5 f55920e832196c1ddcbf854acc6ebded), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' then
    raise notice 'w3 refinery: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 refinery refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'AMASSOMA REFINERY, Amassoma River Refining Ltd: the plan for one month. Every price is illustrative, in US dollars; yields are volume fractions. Streams: naphtha, reformate, kero, gasoil, ulsd, residue, offgas. Crudes: Amenam Blend (illustrative) at 79.4 dollars a barrel, up to 1600000 barrels, yields naphtha 0.24, kero 0.16, gasoil 0.3, residue 0.27, offgas 0.03; Okono (illustrative) at 76.1 dollars a barrel, up to 1200000 barrels, yields naphtha 0.17, kero 0.14, gasoil 0.33, residue 0.34, offgas 0.02; Qua Iboe (illustrative) at 75.2 dollars a barrel, availability typed as 0 (the cargo was cancelled), yields naphtha 0.25, kero 0.15, gasoil 0.31, residue 0.26, offgas 0.03. Units: Crude distillation, capacity 2300000 barrels, operating cost 1.35 dollars a barrel, no feed (the crude unit); Naphtha reformer, capacity 380000 barrels, operating cost 2.85 dollars a barrel, feed naphtha, yields reformate 0.86, offgas 0.09; Diesel hydrotreater, capacity 600000 barrels, operating cost 1.9 dollars a barrel, feed gasoil, yields ulsd 0.97, offgas 0.02. Products: Gasoline at 109.5 dollars a barrel, up to 400000 barrels, made from reformate 1; Naphtha export at 71.8 dollars a barrel, up to 250000 barrels, made from naphtha 1; Jet A-1 at 104.2 dollars a barrel, up to 350000 barrels, made from kero 1; Diesel (ULSD) at 103.6 dollars a barrel, up to 700000 barrels, made from ulsd 1; Gasoil export at 88 dollars a barrel, up to 300000 barrels, made from gasoil 1; Fuel oil at 58.3 dollars a barrel, up to 900000 barrels, made from residue 1. Every demand floor is 0. Give six numbers from the optimal plan. (1) The total crude run, to the whole barrel. (2) The crude unit''s utilisation, in percent to two decimals. (3) The plan margin for the month, to the whole dollar. (4) The gross margin per barrel of crude, to the cent. (5) What one more barrel of naphtha is worth to the plan, in dollars a barrel to the cent. (6) What one more barrel of gasoil is worth to the plan, in dollars a barrel to the cent. Read the figures in the Refinery Planning & Scheduling Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'refinery' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 refinery refused: refinery/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'f55920e832196c1ddcbf854acc6ebded' and fields = '[{"key": "amassoma_crude_run_bbl", "tol": 0.5, "unit": "barrels", "label": "Total crude run of the optimal plan", "expected": 1880000}, {"key": "amassoma_cdu_utilisation_pct", "tol": 0.005, "unit": "percent", "label": "Utilisation of the crude unit", "expected": 81.73913043}, {"key": "amassoma_plan_margin_usd", "tol": 0.5, "unit": "US dollars", "label": "Plan margin for the month", "expected": 8170744}, {"key": "amassoma_gross_margin_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Gross margin per barrel of crude", "expected": 4.34614043}, {"key": "amassoma_naphtha_value_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Value to the plan of one more barrel of naphtha", "expected": 91.32}, {"key": "amassoma_gasoil_value_per_bbl", "tol": 0.005, "unit": "US dollars a barrel", "label": "Value to the plan of one more barrel of gasoil", "expected": 88.06733333}]'::jsonb) from public.academy_capstones where app_slug = 'refinery' and tier = 'intermediate' and active) is not true then
    raise exception 'w3 refinery refused: refinery/intermediate does not read back as its W3 form';
  end if;

  raise notice 'w3 refinery: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
